WC_Subscription::contains_unavailable_pr.source:
public function contains_unavailable_product() {
	/** @var WC_Order_Item_Product $line_item */
	foreach ( $this->get_items() as $line_item ) {
		$product = $line_item->get_product();

		// Product doesn't exist (deleted).
		if ( ! $product instanceof WC_Product ) {
			return true;
		}

		// If the product is a subscription variation, use the parent product.
		if ( $product->is_type( 'subscription_variation' ) ) {
			$parent_product_id = $product->get_parent_id();
			$product           = wc_get_product( $parent_product_id );
		}

		// Check if product is published. Products with other statuses (draft, trash, private)
		// are not available for purchase or resubscribe.
		$product_status = $product->get_status();
		if ( 'publish' !== $product_status ) {
			return true;
		}
	}

	return false;
}

WC_Subscription::is_manual.source:
public function is_manual() {
	$gateways_handler = WC_Subscriptions_Core_Plugin::instance()->get_gateways_handler_class();

	if ( WCS_Staging::is_duplicate_site() || true === $this->get_requires_manual_renewal() || false === $gateways_handler::has_available_payment_method( $this ) ) {
		$is_manual = true;
	} else {
		$is_manual = false;
	}

	return apply_filters( 'woocommerce_subscription_is_manual', $is_manual, $this );
}

WC_Subscription::calculate_next_payment_.source:
protected function calculate_next_payment_date() {
	$next_payment_date = 0;

	// If the subscription is not active, there is no next payment date
	$start_time        = $this->get_time( 'start' );
	$next_payment_time = $this->get_time( 'next_payment' );
	$trial_end_time    = $this->get_time( 'trial_end' );
	$last_payment_time = max( $this->get_time( 'last_order_date_created' ), $this->get_time( 'last_order_date_paid' ) );
	$end_time          = $this->get_time( 'end' );

	// If the subscription has a free trial period, and we're still in the free trial period, the next payment is due at the end of the free trial
	if ( $trial_end_time > current_time( 'timestamp', true ) ) {

		$next_payment_timestamp = $trial_end_time;

	} else {

		$use_scheduled_date = false;
		$from_timestamp     = 0;

		// The next payment date is {interval} billing periods from the start date, trial end date or last payment date
		if ( 0 !== $next_payment_time && $next_payment_time < gmdate( 'U' ) && ( ( 0 !== $trial_end_time && 1 >= $this->get_payment_count() ) || WC_Subscriptions_Synchroniser::subscription_contains_synced_product( $this ) ) ) {
			$from_timestamp = $next_payment_time;
		} elseif ( $last_payment_time >= $start_time && apply_filters( 'wcs_calculate_next_payment_from_last_payment', true, $this ) ) {
			$from_timestamp = $last_payment_time;
		} elseif ( $last_payment_time < $start_time && $next_payment_time > $start_time && $next_payment_time >= ( time() + 2 * HOUR_IN_SECONDS ) ) {
			// The last order predates the subscription's start date, so there is no last payment to
			// calculate forward from, and the scheduled next payment hasn't fallen due yet. That
			// scheduled date is the next payment date itself; adding a billing interval to it would
			// return a date one billing period too late. The 2 hour boundary mirrors the default value
			// of the activation path's 'woocommerce_subscription_activation_next_payment_date_threshold'
			// filter, so under default settings the two paths agree about the same stored date.
			$use_scheduled_date = true;
		} elseif ( $next_payment_time > $start_time ) { // Use the currently scheduled next payment as the base, adding an interval, to preserve the billing schedule
			$from_timestamp = $next_payment_time;
		} else {
			$from_timestamp = $start_time;
		}

		if ( $use_scheduled_date ) {
			$next_payment_timestamp = $next_payment_time;
		} else {
			$next_payment_timestamp = wcs_add_time( $this->get_billing_interval(), $this->get_billing_period(), $from_timestamp, 'offset_site_time' );

			// Make sure the next payment is more than 2 hours in the future, this ensures changes to the site's timezone because of daylight savings will never cause a 2nd renewal payment to be processed on the same day
			$i = 1;
			while ( $next_payment_timestamp < ( current_time( 'timestamp', true ) + 2 * HOUR_IN_SECONDS ) && $i < 3000 ) {
				$next_payment_timestamp = wcs_add_time( $this->get_billing_interval(), $this->get_billing_period(), $next_payment_timestamp, 'offset_site_time' );
				$i += 1;
			}
		}
	}

	// If the subscription has an end date and the next billing period comes after that, return 0
	if ( 0 != $end_time && ( $next_payment_timestamp + 23 * HOUR_IN_SECONDS ) > $end_time ) {
		$next_payment_timestamp = 0;
	}

	if ( $next_payment_timestamp > 0 ) {
		$next_payment_date = gmdate( 'Y-m-d H:i:s', $next_payment_timestamp );
	}

	return $next_payment_date;
}

WCS_User_Change_Status_Handler::change_u.source:
public static function change_users_subscription( $subscription, $new_status ) {
	/** @var WC_Subscription $subscription */
	$subscription = ( ! is_object( $subscription ) ) ? wcs_get_subscription( $subscription ) : $subscription;
	$changed      = false;

	do_action( 'woocommerce_before_customer_changed_subscription_to_' . $new_status, $subscription );

	switch ( $new_status ) {
		case 'active':
			if ( ! $subscription->needs_payment() ) {
				$subscription->update_status( $new_status );
				$subscription->add_order_note( _x( 'Subscription reactivated by the subscriber from their account page.', 'order note left on subscription after user action', 'woocommerce-subscriptions' ) );
				wc_add_notice( _x( 'Your subscription has been reactivated.', 'Notice displayed to user confirming their action.', 'woocommerce-subscriptions' ), 'success' );
				$changed = true;
			} else {
				wc_add_notice( __( 'You can not reactivate that subscription until paying to renew it. Please contact us if you need assistance.', 'woocommerce-subscriptions' ), 'error' );
			}
			break;
		case 'on-hold':
			if ( wcs_can_user_put_subscription_on_hold( $subscription ) ) {
				$subscription->update_status( $new_status );
				$subscription->add_order_note( _x( 'Subscription put on hold by the subscriber from their account page.', 'order note left on subscription after user action', 'woocommerce-subscriptions' ) );
				wc_add_notice( _x( 'Your subscription has been put on hold.', 'Notice displayed to user confirming their action.', 'woocommerce-subscriptions' ), 'success' );
				$changed = true;
			} else {
				wc_add_notice( __( 'You can not suspend that subscription - the suspension limit has been reached. Please contact us if you need assistance.', 'woocommerce-subscriptions' ), 'error' );
			}
			break;
		case 'cancelled':
			$subscription->maybe_cancel();
			$subscription->add_order_note( _x( 'Subscription cancelled by the subscriber from their account page.', 'order note left on subscription after user action', 'woocommerce-subscriptions' ) );
			wc_add_notice( _x( 'Your subscription has been cancelled.', 'Notice displayed to user confirming their action.', 'woocommerce-subscriptions' ), 'success' );
			$changed = true;
			break;
	}

	if ( $changed ) {
		do_action( 'woocommerce_customer_changed_subscription_to_' . $new_status, $subscription );
	}
}
